-- DOCUMENTATION ONLY. PostgreSQL 16. Never execute from this project.
-- ids are generated by the application (no DB defaults).

CREATE TABLE invitations (
  clinic_id     uuid NOT NULL,
  id            uuid NOT NULL,
  membership_id uuid NOT NULL,
  email         text NOT NULL,
  status        text NOT NULL CHECK (status IN ('pending','accepted','cancelled')),
  sent_at       timestamptz NOT NULL,
  responded_at  timestamptz NULL,
  PRIMARY KEY (clinic_id, id),
  FOREIGN KEY (clinic_id, membership_id) REFERENCES memberships (clinic_id, id)
);
CREATE INDEX invitations_clinic_status_idx ON invitations (clinic_id, status);

ALTER TABLE invitations ENABLE ROW LEVEL SECURITY;
ALTER TABLE invitations FORCE ROW LEVEL SECURITY;
CREATE POLICY invitations_tenant_isolation ON invitations
  USING (clinic_id = current_setting('app.clinic_id')::uuid)
  WITH CHECK (clinic_id = current_setting('app.clinic_id')::uuid);
